/**
 * Project issue list; parses filters from `await searchParams`.
 *
 * Owner D. The filter is rebuilt from the URL on every render rather than kept
 * in component state, so a filtered list is a shareable link.
 *
 * Must call (do not reimplement): can
 */

import Link from "next/link";
import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { PENDING_ISSUE_ID } from "@/actions/_lib/permission-resources";
import { IssueList } from "@/components/domain/issue/issue-list";
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { issueFilterSchema } from "@/schemas/issue";
import { searchParamsPaginationSchema } from "@/schemas/pagination";
import { getIssue, listIssues } from "@/server/services/issue-service";
import { ISSUE_STATUSES, type IssueStatus, type IssueWithRelations } from "@/types/issue";
import { loadProjectContext } from "../../../_lib/project-context";

type PageParams = { orgSlug: string; projectSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Issues",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug, projectSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor, project } = await loadProjectContext(orgSlug, projectSlug);

  const mayRead = can(actor, "issue:read", {
    kind: "issue",
    orgId: org.id,
    projectId: project.id,
    issueId: PENDING_ISSUE_ID,
    authorId: actor.userId,
    assigneeId: actor.userId,
  });
  if (!mayRead) {
    notFound();
  }

  const mayCreate = can(actor, "issue:create", {
    kind: "issue",
    orgId: org.id,
    projectId: project.id,
    issueId: PENDING_ISSUE_ID,
    authorId: actor.userId,
    assigneeId: null,
  });

  const pagination = searchParamsPaginationSchema.parse(search);
  const statuses = parseStatuses(search.status);

  // The filter goes through the shared schema so an unparseable URL is a
  // rejected filter rather than a malformed repository query.
  const filter = issueFilterSchema.parse({
    orgId: org.id,
    projectId: project.id,
    ...(statuses.length > 0 ? { status: statuses } : {}),
    ...(typeof search.q === "string" ? { query: search.q } : {}),
    includeArchived: search.archived === "1",
    limit: pagination.perPage,
    cursor: pagination.cursor ?? null,
  });

  const page = await listIssues(actor, filter);
  const rows: IssueWithRelations[] = await Promise.all(
    page.items.map((issue) => getIssue(actor, org.id, issue.id)),
  );

  return (
    <div className="space-y-6">
      <div className="flex items-baseline justify-between">
        <p className="text-sm text-slate-600">
          {page.total} issues in {project.name}
        </p>
        {mayCreate ? (
          <Link
            href={`/${orgSlug}/projects/${projectSlug}/issues/new`}
            className="rounded-md bg-indigo-600 px-3 py-1.5 text-sm font-medium text-white"
          >
            New issue
          </Link>
        ) : null}
      </div>

      {rows.length === 0 ? (
        <EmptyState
          title="No issues match this filter"
          description="Clear the filter, or file the first issue in this project."
        />
      ) : (
        <IssueList issues={rows} actor={actor} />
      )}
    </div>
  );
}

function parseStatuses(raw: string | string[] | undefined): IssueStatus[] {
  const values = Array.isArray(raw) ? raw : raw === undefined ? [] : [raw];
  return values.filter((value): value is IssueStatus =>
    (ISSUE_STATUSES as readonly string[]).includes(value),
  );
}
/**
 * Streams the issue CSV; requires the `csv_export` flag.
 *
 * Owner D. Query parameters are parsed with `exportIssuesSchema` — the same
 * schema the export UI submits — so `?includeArchived=true` cannot mean one
 * thing in the form and another here.
 *
 * Must call (do not reimplement): can, isEnabled, toCsv
 */

import { PENDING_ISSUE_ID, PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { csvResponseHeaders, toCsv } from "@/lib/csv";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { exportIssuesSchema } from "@/schemas/export";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { listIssues } from "@/server/services/issue-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { Issue } from "@/types/issue";

export const dynamic = "force-dynamic";

const EXPORT_PAGE_LIMIT = 100;

const COLUMNS: readonly string[] = [
  "number",
  "title",
  "status",
  "priority",
  "assigneeId",
  "authorId",
  "dueAt",
  "createdAt",
  "updatedAt",
];

export async function GET(request: Request): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    const actor = await getActor(orgSlug);
    const { organization } = await getOrganizationSummary(actor, actor.orgId);

    if (!isEnabled("csv_export", buildFlagContext(actor, organization))) {
      return failure("forbidden", "CSV export is not included in this plan.");
    }

    const allowed = can(actor, "issue:read", {
      kind: "issue",
      orgId: actor.orgId,
      projectId: PENDING_PROJECT_ID,
      issueId: PENDING_ISSUE_ID,
      authorId: actor.userId,
      assigneeId: actor.userId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot export issues in this organization.");
    }

    const parsed = exportIssuesSchema.safeParse({
      orgId: actor.orgId,
      projectId: url.searchParams.get("projectId") ?? undefined,
      includeArchived: url.searchParams.get("includeArchived") ?? false,
      format: url.searchParams.get("format") ?? "csv",
    });
    if (!parsed.success) {
      return failure("validation_failed", "Bad export parameters.");
    }

    const page = await listIssues(actor, {
      orgId: parsed.data.orgId,
      projectId: parsed.data.projectId,
      includeArchived: parsed.data.includeArchived,
      limit: EXPORT_PAGE_LIMIT,
    });

    if (parsed.data.format === "json") {
      return Response.json({ items: page.items, total: page.total });
    }

    const csv = toCsv(page.items.map(toRow), COLUMNS);
    return new Response(csv, {
      headers: csvResponseHeaders(`taskflow-issues-${organization.slug}.csv`),
    });
  } catch (error) {
    return errorResponse(error);
  }
}

/** Flattens an `Issue` into the scalar row shape `toCsv` accepts. */
function toRow(issue: Issue): Record<string, string | number | boolean | null> {
  return {
    number: issue.number,
    title: issue.title,
    status: issue.status,
    priority: issue.priority,
    assigneeId: issue.assigneeId,
    authorId: issue.authorId,
    dueAt: issue.dueAt,
    createdAt: issue.createdAt,
    updatedAt: issue.updatedAt,
  };
}

