const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** True for a real calendar date written `YYYY-MM-DD`. */
export function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE.exec(value);
  if (!match) return false;
  const [, year, month, day] = match.map(Number) as [number, number, number, number];
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/**
 * The exclusive upper bound behind a `due_before` filter. A calendar date is
 * read in UTC and includes that whole day, so the bound is the following
 * midnight; a full timestamp is its own bound.
 */
export function dueBeforeBound(value: string): IsoTimestamp {
  if (isCalendarDate(value)) {
    return toIsoTimestamp(new Date(Date.parse(`${value}T00:00:00.000Z`) + DAY_MS));
  }
  return toIsoTimestamp(parseIso(value as IsoTimestamp));
}
EOF

