import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("northwind-issues");
  acme = await createTenant("acme-issues");
});

afterAll(() => {
  cleanup();
});

