    const l2 = await labelRepo.insertLabel({ orgId: t.org.id, name: "reg", color: "#00ff00" } as any);
    const a = await mk({ title: "both", labelIds: [l1.id, l2.id], dueAt: "2026-10-09T15:00:00.000Z", assigneeId: t.userIds.owner });
    const b = await mk({ title: "one", labelIds: [l1.id], status: "done", dueAt: "2026-10-10T00:00:00.000Z" });
    const c = await mk({ title: "arch" });
    await issueRepo.archiveIssue(t.org.id, c.id);
    const run = async (q: string) => {
      const f = issueFilterSchema.parse({ ...parseIssueFilterParams(new URLSearchParams(q)), orgId: t.org.id, limit: 25 });
      const p = await issueService.listIssues(t.actors.owner, f);
      return [p.items.map((i) => i.title).sort(), p.total];
    };
    console.log(await run(`label=${l1.id},${l2.id}`));
    console.log(await run(`assignee=none`));
    console.log(await run(`assignee=me`));
    console.log(await run(`due_before=2026-10-09`));
    console.log(await run(`due_before=2026-10-09T15:00:00Z`));
    console.log(await run(`status=open`));
    console.log(await run(`archived=only`));
    console.log(await run(`archived=1`));
    console.log(issueFilterSchema.safeParse({ orgId: t.org.id, status: ["open", "closed"] }).success, issueFilterSchema.safeParse({ orgId: t.org.id, status: ["bogus"] }).success);
    const p = await issueService.listIssues(t.actors.owner, { orgId: t.org.id, limit: 25, status: ["closed"], assigneeId: "me" } as any);
    console.log(p.total);
  });
});
EOF
