import { afterAll, beforeAll, describe, it, vi } from "vitest";
import { appendFileSync } from "node:fs";
vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueService from "@/server/services/issue-service";
import { issueFilterSchema } from "@/schemas/issue";
import { parseIssueFilterParams } from "@/hooks/issue-filter-params";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
const log = (...a: unknown[]) => appendFileSync("/tmp/zz-out.txt", JSON.stringify(a) + "\n");
let cleanup: () => void;
let t: any;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); t = await createTenant("tmpx"); });
afterAll(() => cleanup());

describe("tmp", () => {
  it("works", async () => {
    const mk = async (o: any) => issueRepo.insertIssue({ ...issueInput(t.org.id, t.project.id, o), ...o }, t.userIds.owner, await issueRepo.nextIssueNumber(t.org.id, t.project.id));
    const l1 = await labelRepo.insertLabel({ orgId: t.org.id, name: "bug", color: "#ff0000" } as any);
    const l2 = await labelRepo.insertLabel({ orgId: t.org.id, name: "reg", color: "#00ff00" } as any);
    await mk({ title: "both", labelIds: [l1.id, l2.id], dueAt: "2026-10-09T15:00:00.000Z", assigneeId: t.userIds.owner });
    await mk({ title: "one", labelIds: [l1.id], status: "done", dueAt: "2026-10-10T00:00:00.000Z" });
    const c = await mk({ title: "arch" });
    await issueRepo.archiveIssue(t.org.id, c.id);
    const run = async (q: string) => {
      const f = issueFilterSchema.parse({ ...parseIssueFilterParams(new URLSearchParams(q)), orgId: t.org.id, limit: 25 });
      const p = await issueService.listIssues(t.actors.owner, f);
      return [q, p.items.map((i) => i.title).sort(), p.total];
    };
    for (const q of [`label=${l1.id},${l2.id}`, `label=${l1.id}`, "assignee=none", "assignee=me", "due_before=2026-10-09", "due_before=2026-10-09T15:00:00Z", "status=open", "status=closed", "archived=only", "archived=1", ""]) log(await run(q));
    log(issueFilterSchema.safeParse({ orgId: t.org.id, status: ["open", "closed"] }).success, issueFilterSchema.safeParse({ orgId: t.org.id, status: ["bogus"] }).success);
    const p = await issueService.listIssues(t.actors.owner, { orgId: t.org.id, limit: 25, status: ["closed"], assigneeId: "me" } as any);
    log("closed+me", p.total);
  });
});
EOF
